table inet filter {
    set blacklist4 {
        type ipv4_addr; flags interval;
        elements = { 203.0.113.0/24, 198.51.100.7 }
    }
    chain input {
        type filter hook input priority 0; policy drop;
        ct state established,related accept
        iifname "lo" accept
        ip saddr @blacklist4 drop
        tcp dport { 22, 80, 443 } accept
    }
}

#!/usr/sbin/nft -f
flush ruleset

table inet filter {
    chain input {
        type filter hook input priority 0; policy drop;
        ct state invalid drop
        ct state established,related accept
        iifname "lo" accept
        ip protocol icmp accept
        ip6 nexthdr ipv6-icmp accept
        tcp dport { 22, 80, 443 } ct state new accept
        counter reject with icmpx type admin-prohibited
    }
}

nft add element inet filter blacklist4 { 198.51.100.7 }
nft list set inet filter blacklist4
nft delete element inet filter blacklist4 { 198.51.100.7 }

server {
    listen 80;
    server_name app.example.com;
    location / { return 200 "ok\n"; }
}
